// record.ts records the display width reference of std text (SQ2) from
// Bun.stringWidth (Bun 1.4.4: Unicode East Asian Width, emoji and
// grapheme rules, ANSI escapes stripped), once; no Bun at test time.
//
//   bun record.ts tables > ../../../std/text/width_table.ergo
//   bun record.ts rows   > cells.jsonl
//
// tables: the rune classes std text's Cells reads, as sorted [lo, hi]
// ranges, each probed from Bun one code point at a time:
//   zero  - runs whose lone width is 0;  wide - runs whose lone width is 2;
//   pict  - a pictograph that a ZWJ joins to the one after it (r ZWJ "😀"
//           is 2 wide);
//   join  - a rune that a ZWJ joins to a pictograph before it ("😀" ZWJ r
//           is as wide as "😀");
//   seq   - a rune that a ZWJ sequence takes in after it ("😀" ZWJ "😀" r
//           is 2 wide: spacing marks and a few wide extenders);
//   vs16  - a narrow rune that U+FE0F makes 2 wide;
//   modBase - a rune that a skin tone modifier (U+1F3FB..U+1F3FF) after it
//           adds nothing to.
// rows: generated texts of whole clusters (ASCII words, CJK, a letter with
// combining marks, emoji, emoji with a modifier, ZWJ sequences, flags,
// VS16 forms, keycaps, controls, SGR and OSC 8 escapes), each with Bun's
// width: ["cells", text, width].
const mode = process.argv[2];
const W = (s: string) => Bun.stringWidth(s);
const ZWJ = "\u200d", VS16 = "\ufe0f", TONE = "\u{1f3fb}", GRIN = "\u{1f600}";
const cps: number[] = [];
for (let cp = 0; cp <= 0x10ffff; cp++) if (cp < 0xd800 || cp > 0xdfff) cps.push(cp);
const ranges = (pred: (cp: number) => boolean) => {
  const out: [number, number][] = [];
  for (const cp of cps) {
    if (!pred(cp)) continue;
    const last = out[out.length - 1];
    if (last && last[1] === cp - 1) last[1] = cp;
    else out.push([cp, cp]);
  }
  return out;
};
const lone = new Map<number, number>();
for (const cp of cps) lone.set(cp, W(String.fromCodePoint(cp)));
const tables = {
  zero: ranges((cp) => lone.get(cp) === 0),
  wide: ranges((cp) => lone.get(cp) === 2),
  pict: ranges((cp) => lone.get(cp)! > 0 && W(String.fromCodePoint(cp) + ZWJ + GRIN) === 2),
  join: ranges((cp) => lone.get(cp)! > 0 && W(GRIN + ZWJ + String.fromCodePoint(cp)) === 2),
  seq: ranges((cp) => lone.get(cp)! > 0 && W(GRIN + ZWJ + GRIN + String.fromCodePoint(cp)) === 2),
  vs16: ranges((cp) => lone.get(cp) === 1 && W(String.fromCodePoint(cp) + VS16) === 2),
  modBase: ranges((cp) => { const w = lone.get(cp)!; return w === 2 && W(String.fromCodePoint(cp) + TONE) === w; }),
};
if (mode === "tables") {
  const list = (name: string, rs: [number, number][], doc: string) =>
    `// ${name} ${doc}\nlet ${name} = []int{${rs.map(([a, b]) => `0x${a.toString(16)}, 0x${b.toString(16)}`).join(", ")}}\n`;
  console.log(`// Code generated by internal/sketch/eval/testdata/textwidth/record.ts tables; DO NOT EDIT.
// The rune classes of Cells (width.ergo), recorded from Bun ${Bun.version}'s
// stringWidth one code point at a time: sorted inclusive ranges, a pair of
// ints each.

${list("zeroRunes", tables.zero, "are the runes a terminal gives no column (controls, combining marks, format characters).")}
${list("wideRunes", tables.wide, "are the runes a terminal gives two columns (East Asian Wide and Fullwidth, emoji presentation).")}
${list("pictRunes", tables.pict, "are the pictographs a ZWJ joins to the pictograph after it.")}
${list("joinRunes", tables.join, "are the runes a ZWJ joins to the pictograph before it.")}
${list("seqRunes", tables.seq, "are the runes a ZWJ sequence takes in after it.")}
${list("vs16Runes", tables.vs16, "are the narrow runes U+FE0F turns into two-column emoji.")}
${list("modBaseRunes", tables.modBase, "are the emoji a skin tone modifier joins.")}`.trimEnd());
} else if (mode === "rows") {
  let seed = 0x5eed;
  const rnd = (n: number) => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return (seed >>> 8) % n; };
  const pick = <T>(xs: T[]) => xs[rnd(xs.length)];
  const inRanges = (rs: [number, number][]) => { const [a, b] = pick(rs); return String.fromCodePoint(a + rnd(b - a + 1)); };
  const words = ["a", "go", "ergo", "Hello", "x1", "café", "naïve", "über", "日本語", "한국어", "ｶﾀｶﾅ", "Ａ", "α", "ж", "→", "™"];
  const marks = ["\u0301", "\u0308", "\u0323", "\u20dd", "\u0670"];
  const clusters: (() => string)[] = [
    () => pick(words),
    () => " ",
    () => inRanges(tables.wide.filter(([a]) => a >= 0x3000 && a < 0x10000)),
    () => pick(["a", "e", "o", "n"]) + pick(marks) + (rnd(2) ? pick(marks) : ""),
    () => inRanges(tables.pict.filter(([a]) => lone.get(a) === 2)),
    () => inRanges(tables.modBase) + String.fromCodePoint(0x1f3fb + rnd(5)),
    () => [0, 1, 2].slice(0, 2 + rnd(2)).map(() => inRanges(tables.pict)).join(ZWJ),
    () => inRanges(tables.pict) + ZWJ + inRanges(tables.join),
    () => inRanges(tables.pict) + ZWJ + inRanges(tables.join) + inRanges(tables.seq),
    () => inRanges(tables.pict) + ZWJ,
    () => String.fromCodePoint(0x1f1e6 + rnd(26)) + String.fromCodePoint(0x1f1e6 + rnd(26)),
    () => inRanges(tables.vs16) + VS16,
    () => pick(["#", "*", "0", "5", "9"]) + VS16 + "\u20e3",
    () => pick(["\t", "\x07", "\x7f", "\u200b", "\u00ad"]),
    () => "\x1b[" + pick(["0", "1", "31", "1;32", "38;5;208", "38;2;1;2;3"]) + "m",
    () => "\x1b]8;;https://x.example/" + pick(["a", "b"]) + "\x07" + pick(words) + "\x1b]8;;\x07",
    () => "\x1b[" + pick(["2K", "?25l", "10;4H", "A"]),
  ];
  const seen = new Set<string>();
  let rows = 0;
  while (rows < 3000) {
    const n = 1 + rnd(8);
    let s = "";
    for (let i = 0; i < n; i++) s += pick(clusters)();
    if (seen.has(s)) continue;
    seen.add(s);
    console.log(JSON.stringify(["cells", s, W(s)]));
    rows++;
  }
  // each class's range ends, alone
  for (const [name, rs] of Object.entries(tables)) {
    for (const [a, b] of rs) for (const cp of [a, b]) console.log(JSON.stringify(["cells", String.fromCodePoint(cp), lone.get(cp), name]));
  }
} else {
  console.error("usage: bun record.ts tables|rows");
  process.exit(2);
}
